// El nodo Merge ya ha combinado los datos del Trigger y de Redis.
const userInput = $json.chatInput;
const schemaString = $json.propertyName;

if (typeof userInput === 'undefined') {
  throw new Error("El input del usuario ('chatInput') no fue encontrado.");
}

let enriched_prompt;

if (schemaString) {
  try {
    const fullSchema = JSON.parse(schemaString);

    // --- LÓGICA DE TRANSFORMACIÓN A ESQUEMA ENRIQUECIDO ---
    const enrichedSchema = fullSchema.reduce((acc, collection) => {
      const fields = collection.schema.reduce((fieldAcc, field) => {
        // Si el campo es de tipo 'select', incluimos sus opciones.
        if (field.type === 'select') {
          fieldAcc[field.name] = {
            type: 'select',
            options: field.options.values || [] // Aseguramos que 'values' exista
          };
        } else {
          // Para otros tipos de campo, mantenemos el formato simple.
          fieldAcc[field.name] = field.type;
        }
        return fieldAcc;
      }, {});
      acc[collection.name] = fields;
      return acc;
    }, {});

    const formattedSchema = JSON.stringify(enrichedSchema, null, 2);

    enriched_prompt = `CONOCIMIENTO DE CONTEXTO (ESQUEMA DE BASE DE DATOS ENRIQUECIDO):\n\`\`\`json\n${formattedSchema}\n\`\`\`\n\nSOLICITUD DEL USUARIO:\n${userInput}`;

  } catch (e) {
    console.error("Error al parsear o enriquecer el esquema desde Redis:", e.message);
    enriched_prompt = `SOLICITUD DEL USUARIO:\n${userInput}`;
  }
} else {
  enriched_prompt = `SOLICITUD DEL USUARIO:\n${userInput}`;
}

const outputItem = items[0];
outputItem.json.chatInput = enriched_prompt;
delete outputItem.json.propertyName;

return [outputItem];
